 $computerName,
 $macAddress,
 $cmSiteCode,
 $vCenter_User,
 $vCenter_User_Pass,
 $remoteMachineName
 )

# Variables
$activityName = 'Import CM Device'
$notes = "Import CM Device"
$success = "false"

#Build credentials
$credential = New-Object System.Management.Automation.PSCredential -ArgumentList @($vCenter_User, (ConvertTo-SecureString -String $vCenter_User_Pass -AsPlainText -Force))

try {

 $psDriveName = 'SCOLogPath'
 $strArray = $logPath.Split('\', [System.StringSplitOptions]::RemoveEmptyEntries)
 $fileName = $strArray | Where-Object { $_ -like '*.log' }
 $filePath = '\\' + (($strArray | Where-Object { $_ -ne $fileName }) -join '\')

 if (-not (Test-Path $psDriveName)) {
    $psDrive = New-PSDrive -Name $psDriveName -PSProvider FileSystem -Root $filePath -Credential $credential
 }

 $localPath = $psDriveName + ':\' + $fileName

 if (-not (Test-Path $filePath)) { throw "Test path failed to $filePath" }
 if (-not (Test-Path $localPath)) { throw "Test path failed to $localPath" }


 # Load PowerShell modules
 Import-Module (Join-Path $(Split-Path $env:SMS_ADMIN_UI_PATH) ConfigurationManager.psd1)

    }
    # Load PowerShell modules
        Import-Module (Join-Path $(Split-Path $env:SMS_ADMIN_UI_PATH) ConfigurationManager.psd1)
        $notes = 'Loaded ConfigMgr PowerShell module'

        # Set SCCM drive path
        Set-Location "$($cmSiteCode):" -ErrorAction Stop

        # Process

        #Wait one minute in case a record was just deleted
        Start-Sleep -Seconds 60

        # Does the coputer already exist?
        $cmDevice = Get-CMDevice -Name $computerName -ErrorAction Ignore
        $resID = $cmDevice.ResourceID
        if (-not $resID) {
            # Import device into SCCM
            $importDevice = Import-CMComputerInformation -CollectionName 'All Systems' -ComputerName $computerName -MacAddress $macAddress -ErrorAction Stop

            $tries = 1

            do {
                if ($tries -ge 2) {
                    Start-Sleep -Seconds 60
                }
                $cmDevice = Get-CMDevice -Name $computerName -ErrorAction Ignore
                $tries++
            } 
            while ((-not $cmDevice.ResourceID) -and ($tries -le 20))

            if (-not $cmDevice.ResourceID){
              Throw 'Timed out trying to import device \`d.T.~Ed/{ADC985A7-3AD7-4DA9-A49A-AC92AB8A6320}.{1B85C5E2-FA8A-44E4-9E77-52EC4317806D}\`d.T.~Ed/ into SCCM'
            }
        }

        # Return object
        return $cmDevice
    }
    catch {
        $errorReturn = $_.Exception.Message
        throw $errorReturn
    }
}


try {  
    # Initiate remote PowerShell session (needed for SCO to run native PowerShell version)
    $session = New-PSSession -ComputerName $remoteMachineName -Credential $credential
    Write-Log -Message "Created remote session on $($session.ComputerName.ToUpper())" -LogPath $LogPath

    # Run script block on remote PowerShell session
    $returnData = Invoke-Command -ScriptBlock $cmd -Session $session

    # Process Output
    $resourceId = $cmDevice.ResourceID
    $deviceName = $cmDevice.Name

    if (-not $resourceID){
        #Throw "Device \`d.T.~Ed/{ADC985A7-3AD7-4DA9-A49A-AC92AB8A6320}.{1B85C5E2-FA8A-44E4-9E77-52EC4317806D}\`d.T.~Ed/ was not successfully imported - resourceID variable did not get properly set"
  $notes = "resourceID variable did not get properly set"
    }
 else {
  $notes = "resourceID variable was set"
  $success = "true"
 }
 $results = @{
  success = $success;
  notes = $notes;
  resourceId = $resourceId;
  deviceName = $deviceName;
    } | convertTo-Json
    # Return
    return $results
}
catch {
    $errorReturn = $_.Exception.Message
 $results = @{
      success = $success;
      notes = $notes;
    } | convertTo-Json
    return $results
    throw $errorReturn
}
finally {
    # Always close PowerShell session
    Remove-PSSession -Session $session
}
